reference_css:
* { box-sizing: border-box; }
:root { --ink: #172554; --muted: #475569; --surface: #fff; --accent: #1d4ed8; --soft: #eff6ff; --space: clamp(1rem, 3vw, 2.5rem); }
body { margin: 0; color: var(--ink); background: var(--surface); font: 1rem/1.65 system-ui, sans-serif; }
.site-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem max(1rem, calc((100vw - 74rem) / 2)); }
.brand { font-weight: 850; text-decoration: none; }
.site-header nav { display: flex; flex-wrap: wrap; gap: 1rem; }
.page-shell { width: min(calc(100% - 2rem), 74rem); margin-inline: auto; }
.hero-grid { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(14rem, .8fr); align-items: center; gap: var(--space); padding-block: clamp(3rem, 9vw, 8rem); }
h1 { font-size: clamp(2.4rem, 6vw, 5rem); line-height: 1.02; letter-spacing: -.04em; max-width: 12ch; }
.lead { font-size: 1.2rem; max-width: 52ch; color: var(--muted); }
.eyebrow { color: var(--accent); text-transform: uppercase; font-size: .78rem; font-weight: 800; letter-spacing: .12em; }
.hero-art { display: grid; place-items: center; min-height: 18rem; position: relative; border-radius: 2rem; background: linear-gradient(135deg, #dbeafe, #fef3c7); overflow: hidden; }
.hero-art span { display: block; width: 8rem; aspect-ratio: 1; border-radius: 50%; background: #1d4ed8; opacity: .85; }
.hero-art span:nth-child(2) { width: 11rem; background: #f97316; margin-inline-start: 5rem; margin-block-start: -5rem; }
.hero-art span:nth-child(3) { width: 5rem; background: #0f766e; margin-inline-start: -7rem; margin-block-start: -3rem; }
.button { display: inline-block; border: 2px solid var(--accent); border-radius: .5rem; padding: .75rem 1rem; color: #fff; background: var(--accent); font-weight: 700; text-decoration: none; }
.button-small { padding: .5rem .75rem; }
.section { padding-block: clamp(2.5rem, 6vw, 5rem); }
.feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
.feature-card, .pricing-callout, .contact-panel { padding: 1.25rem; border: 1px solid #cbd5e1; border-radius: 1rem; background: var(--soft); }
.story-panel { padding-inline: max(1rem, calc((100vw - 74rem) / 2)); background: #0f172a; color: white; }
.story-panel blockquote { max-width: 45ch; font-size: clamp(1.3rem, 3vw, 2rem); }
.site-footer { padding: 2rem; color: var(--muted); text-align: center; }
:focus-visible { outline: 3px solid #0f766e; outline-offset: 3px; }
@media (max-width: 48rem) { .hero-grid { grid-template-columns: 1fr; } .feature-grid { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; } }
